    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const gameoverEl = document.getElementById('gameover');
    const finalScoreEl = document.getElementById('finalScore');

    const LOGICAL_W = 380;
    const LOGICAL_H = 640;
    const groundY = LOGICAL_H - 90;
    const GRAVITY = 0.9;
    const JUMP_V = -14;

    const sprite = new Image();
    sprite.src = 'data:image/png;base64,';

    const pillSprite = new Image();
    pillSprite.src = 'data:image/png;base64,';

    const player = { x: 60, y: 0, w: 40, h: 46, vy: 0, jumping: false };

    let obstacles = [];
    let pills = [];
    let speed = 3.5;
    let frame = 0;
    let score = 0;
    let gameOver = false;
    let ready = false;

    const OBSTACLE_TYPES = [
      { w: 22, h: 32, color: '#ff5d5d' },
      { w: 30, h: 22, color: '#7c4dff' },
      { w: 18, h: 46, color: '#ffb703' },
    ];

    function fitCanvas() {
      const wrap = document.getElementById('game-wrap');
      const reserved = wrap.querySelector('h1').offsetHeight
        + wrap.querySelector('.instructions').offsetHeight
        + 24;
      const maxW = Math.min(window.innerWidth * 0.98, 480);
      const maxH = Math.max(window.innerHeight - reserved, 200);
      const scale = Math.min(maxW / LOGICAL_W, maxH / LOGICAL_H);

      canvas.style.width = Math.round(LOGICAL_W * scale) + 'px';
      canvas.style.height = Math.round(LOGICAL_H * scale) + 'px';

      const dpr = window.devicePixelRatio || 1;
      canvas.width = LOGICAL_W * dpr;
      canvas.height = LOGICAL_H * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      if (gameOver || !frame) drawFrame();
    }

    function resetGame() {
      player.y = groundY - player.h;
      player.vy = 0;
      player.jumping = false;
      obstacles = [];
      pills = [];
      speed = 3.5;
      frame = 0;
      score = 0;
      gameOver = false;
      gameoverEl.classList.add('hidden');
      updateScore();
      requestAnimationFrame(loop);
    }

    function updateScore() {
      scoreEl.textContent = `Puntos: ${score}`;
    }

    let audioCtx;
    function playJumpSound() {
      try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') audioCtx.resume();

        const t0 = audioCtx.currentTime;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();

        osc.type = 'square';
        osc.frequency.setValueAtTime(220, t0);
        osc.frequency.exponentialRampToValueAtTime(880, t0 + 0.09);
        osc.frequency.exponentialRampToValueAtTime(440, t0 + 0.18);

        gain.gain.setValueAtTime(0.0001, t0);
        gain.gain.exponentialRampToValueAtTime(0.22, t0 + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.2);

        osc.connect(gain).connect(audioCtx.destination);
        osc.start(t0);
        osc.stop(t0 + 0.22);
      } catch (e) {
        // el navegador no soporta Web Audio; el juego sigue sin sonido
      }
    }

    function jump() {
      if (!ready) return;
      if (gameOver) {
        resetGame();
        return;
      }
      if (!player.jumping) {
        player.vy = JUMP_V;
        player.jumping = true;
        playJumpSound();
      }
    }

    function spawnObstacle() {
      const t = OBSTACLE_TYPES[Math.floor(Math.random() * OBSTACLE_TYPES.length)];
      obstacles.push({ x: LOGICAL_W + 20, y: groundY - t.h, w: t.w, h: t.h, color: t.color, passed: false });
    }

    const PILL_W = 33;
    const PILL_H = 11;

    function spawnPill() {
      const minY = groundY - 190;
      const maxY = groundY - 70;
      const y = minY + Math.random() * (maxY - minY);
      pills.push({ x: LOGICAL_W + 20, y, w: PILL_W, h: PILL_H });
    }

    function playPillSound() {
      try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        if (audioCtx.state === 'suspended') audioCtx.resume();

        const t0 = audioCtx.currentTime;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(660, t0);
        osc.frequency.exponentialRampToValueAtTime(1320, t0 + 0.12);

        gain.gain.setValueAtTime(0.0001, t0);
        gain.gain.exponentialRampToValueAtTime(0.2, t0 + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.15);

        osc.connect(gain).connect(audioCtx.destination);
        osc.start(t0);
        osc.stop(t0 + 0.15);
      } catch (e) {
        // el navegador no soporta Web Audio; el juego sigue sin sonido
      }
    }

    function rectsOverlap(a, b) {
      const padX = 10;
      const padY = 4;
      return a.x + padX < b.x + b.w && a.x + a.w - padX > b.x && a.y + padY < b.y + b.h && a.y + a.h > b.y;
    }

    function touchesPill(a, b) {
      return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    function drawScene() {
      ctx.clearRect(0, 0, LOGICAL_W, LOGICAL_H);

      ctx.fillStyle = '#fff6c8';
      ctx.beginPath();
      ctx.arc(LOGICAL_W - 50, 45, 24, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#3f6626';
      ctx.fillRect(0, groundY, LOGICAL_W, LOGICAL_H - groundY);
      ctx.strokeStyle = '#2d4d1c';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, groundY);
      ctx.lineTo(LOGICAL_W, groundY);
      ctx.stroke();
    }

    function drawObstacles() {
      obstacles.forEach(o => {
        ctx.fillStyle = o.color;
        ctx.beginPath();
        ctx.moveTo(o.x, o.y + o.h);
        ctx.lineTo(o.x + o.w / 2, o.y);
        ctx.lineTo(o.x + o.w, o.y + o.h);
        ctx.closePath();
        ctx.fill();
      });
    }

    function drawPills() {
      pills.forEach(p => {
        if (pillSprite.complete && pillSprite.naturalWidth) {
          ctx.drawImage(pillSprite, p.x, p.y, p.w, p.h);
        }
      });
    }

    function drawPlayer() {
      if (!sprite.complete || !sprite.naturalWidth) return;
      const { x, y, w, h } = player;
      const tilt = player.jumping ? -0.15 : 0;
      ctx.save();
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate(tilt);
      ctx.drawImage(sprite, -w / 2, -h / 2, w, h);
      ctx.restore();
    }

    function drawFrame() {
      drawScene();
      drawObstacles();
      drawPills();
      drawPlayer();
    }

    function endGame() {
      gameOver = true;
      finalScoreEl.textContent = `Puntuación final: ${score}`;
      gameoverEl.classList.remove('hidden');
    }

    function loop() {
      if (gameOver) return;
      frame++;

      player.vy += GRAVITY;
      player.y += player.vy;
      if (player.y > groundY - player.h) {
        player.y = groundY - player.h;
        player.vy = 0;
        player.jumping = false;
      }

      const spawnGap = Math.max(75 - speed * 5, 45);
      if (frame % Math.round(spawnGap) === 0) spawnObstacle();
      if (frame % 150 === 0 && Math.random() < 0.7) spawnPill();

      obstacles.forEach(o => (o.x -= speed));
      obstacles = obstacles.filter(o => o.x + o.w > -10);

      pills.forEach(p => (p.x -= speed));
      pills = pills.filter(p => p.x + p.w > -10);

      for (const o of obstacles) {
        if (!o.passed && o.x + o.w < player.x) {
          o.passed = true;
          score++;
          updateScore();
          if (score % 8 === 0) speed += 0.3;
        }
        if (rectsOverlap(player, o)) {
          endGame();
        }
      }

      pills = pills.filter(p => {
        if (touchesPill(player, p)) {
          score += 3;
          updateScore();
          playPillSound();
          return false;
        }
        return true;
      });

      drawFrame();
      requestAnimationFrame(loop);
    }

    window.addEventListener('keydown', e => {
      if (e.code === 'Space') {
        e.preventDefault();
        jump();
      }
    });
    window.addEventListener('mousedown', jump);
    window.addEventListener('touchstart', e => {
      e.preventDefault();
      jump();
    }, { passive: false });

    window.addEventListener('resize', fitCanvas);
    window.addEventListener('orientationchange', fitCanvas);

    function start() {
      player.h = 46;
      player.w = sprite.naturalWidth ? player.h * (sprite.naturalWidth / sprite.naturalHeight) : 40;
      ready = true;
      fitCanvas();
      resetGame();
    }

    if (sprite.complete) {
      start();
    } else {
      sprite.onload = start;
    }
